import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_naive_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void conv2d_naive_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int N, int C, int H, int W,
    int outC, int kH, int kW,
    int outH, int outW,
    int strideH, int strideW,
    int padH, int padW,
    int dilationH, int dilationW,
    bool has_bias
) {
    int out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (out_idx >= N * outC * outH * outW) return;

    int ow = out_idx % outW;
    int temp = out_idx / outW;
    int oh = temp % outH;
    temp /= outH;
    int oc = temp % outC;
    int n = temp / outC;

    float val = 0.0f;
    if (has_bias) {
        val = bias[oc];
    }

    for (int ic = 0; ic < C; ic++) {
        for (int kh = 0; kh < kH; kh++) {
            for (int kw_ = 0; kw_ < kW; kw_++) {
                int ih = oh * strideH + kh * dilationH - padH;
                int iw = ow * strideW + kw_ * dilationW - padW;
                if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                    float inp_val = input[n * C * H * W + ic * H * W + ih * W + iw];
                    float wt_val = weight[oc * C * kH * kW + ic * kH * kW + kh * kW + kw_];
                    val += inp_val * wt_val;
                }
            }
        }
    }
    output[out_idx] = val;
}

torch::Tensor conv2d_naive_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    bool has_bias
) {
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int outC = weight.size(0);
    int kH = weight.size(2);
    int kW = weight.size(3);

    // Calculate output height/width
    int outH = (H + 2 * pad_h - (dilation_h * (kH - 1) + 1)) / stride_h + 1;
    int outW = (W + 2 * pad_w - (dilation_w * (kW - 1) + 1)) / stride_w + 1;

    auto output = torch::zeros({N, outC, outH, outW}, input.options());

    int total_size = N * outC * outH * outW;
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    conv2d_naive_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, C, H, W,
        outC, kH, kW,
        outH, outW,
        stride_h, stride_w,
        pad_h, pad_w,
        dilation_h, dilation_w,
        has_bias
    );

    return output;
}
"""

conv2d_naive_header = """
torch::Tensor conv2d_naive_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    bool has_bias
);
"""

conv2d_naive = load_inline(
    name="conv2d_naive",
    cpp_sources=conv2d_naive_header,
    cuda_sources=conv2d_naive_source,
    functions=["conv2d_naive_cuda"],
    verbose=False,
    extra_cflags=["-O2"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False
    ):
        super().__init__()
        # For simplicity, ignoring groups > 1 in this naive kernel example
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        # Weight parameter
        self.weight = nn.Parameter(
            torch.randn(out_channels, in_channels, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.bias is None:
            b = torch.tensor([], device=x.device, dtype=x.dtype)
        else:
            b = self.bias
        return conv2d_naive.conv2d_naive_cuda(
            x,
            self.weight,
            b,
            self.stride,
            self.stride,
            self.padding,
            self.padding,
            self.dilation,
            self.dilation,
            self.has_bias
        )
